Qz(a){var s=""+a
return A.b5(a,s+" \u0623\u0635\u0646\u0627\u0641",this.a,s+" \u0635\u0646\u0641\u0627\u064b","\u0635\u0646\u0641 \u0648\u0627\u062d\u062f",s+" \u0635\u0646\u0641","\u0635\u0646\u0641\u0627\u0646",null)},
gE_(){return"\u0627\u0644\u0635\u0646\u0641"},
gQF(){return"\u0627\u0644\u0643\u0645\u064a\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629"},
gQD(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0623\u0635\u0646\u0627\u0641 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0628\u0639\u062f."},
gQE(){return"\u0637\u0628\u0627\u0639\u0629"},
E1(a){return"\u062a\u0639\u0630\u0651\u0631 \u0627\u0644\u062d\u0641\u0638: "+a},
gaeF(){return"\u064a\u0645\u0643\u0646\u0647 \u062a\u062d\u062f\u064a\u062f \u0645\u0646 \u064a\u064f\u0633\u0644\u064e\u0651\u0645 \u0644\u0647 \u0627\u0644\u0635\u0646\u0641 \u0639\u0646\u062f \u0627\u0644\u0645\u0633\u062d"},
