gah1(){return"\u064a\u0636\u064a\u0641 \u062a\u0628\u0648\u064a\u0628 \xab\u0627\u0644\u062d\u0633\u0627\u0628\xbb \u0641\u064a \u0635\u0641\u062d\u0627\u062a \u0627\u0644\u0628\u0648\u062a \u064a\u0639\u0631\u0636 \u0645\u0627 \u0639\u0644\u0649 \u0643\u0644 \u0637\u0628\u064a\u0628 \u0644\u0644\u0645\u062e\u062a\u0628\u0631 (\u0625\u062c\u0645\u0627\u0644\u064a \u0643\u0634\u0641 \u062d\u0633\u0627\u0628 \u0627\u0644\u0637\u0628\u064a\u0628)."},
gagS(){return"\u0631\u0628\u0637"},
ah2(a,b){return"\u0627\u0644\u0623\u0637\u0628\u0627\u0621 \u0627\u0644\u0645\u0631\u062a\u0628\u0637\u0648\u0646: "+a+" \xb7 \u0645\u062d\u0627\u062f\u062b\u0627\u062a \u0627\u0644\u0645\u062e\u062a\u0628\u0631 \u0627\u0644\u062a\u064a \u062a\u0635\u0644\u0647\u0627 \u0627\u0644\u062a\u0646\u0628\u064a\u0647\u0627\u062a: "+b},
gah_(){return"\u0623\u0631\u0633\u0644 \u0647\u0630\u0627 \u0627\u0644\u0631\u0627\u0628\u0637 \u0644\u0623\u0637\u0628\u0627\u0626\u0643. \u064a\u0636\u063a\u0637\u0648\u0646 \xab\u0627\u0628\u062f\u0623\xbb \u0648\u064a\u0634\u0627\u0631\u0643\u0648\u0646 \u0631\u0642\u0645 \u0647\u0627\u062a\u0641\u0647\u0645\u060c \u0641\u064a\u062a\u0639\u0631\u0651\u0641 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0628\u0648\u062a \u0645\u0646 \u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u0645\u062d\u0641\u0648\u0638 \u0641\u064a \u0627\u0644\u0639\u064a\u0627\u062f\u0627\u062a."},
gagY(){return"\u0644\u062a\u0635\u0644\u0643 \u0631\u0633\u0627\u0644\u0629 \u0639\u0646 \u0643\u0644 \u062d\u0627\u0644\u0629 \u064a\u0631\u0633\u0644\u0647\u0627 \u0627\u0644\u0623\u0637\u0628\u0627\u0621\u060c \u0627\u0641\u062a\u062d \u0627\u0644\u0628\u0648\u062a \u0648\u0623\u0631\u0633\u0644:"},
gagZ(){return"\u0631\u0645\u0632 \u062c\u062f\u064a\u062f"},
agR(a){return"\u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0648\u0627\u0631\u062f\u0629 \u0645\u0646 \u0627\u0644\u0628\u0648\u062a \u062a\u064f\u0633\u062c\u064e\u0651\u0644 \u0628\u0627\u0633\u0645 "+a+"."},
gagU(){return"\u0641\u0635\u0644 \u0627\u0644\u0628\u0648\u062a"},
gagW(){return"\u0641\u0635\u0644 \u0627\u0644\u0628\u0648\u062a\u061f"},
agV(a){return"\u0633\u064a\u062a\u0648\u0642\u0641 "+a+" \u0639\u0646 \u0627\u0644\u0631\u062f \u0648\u0633\u064a\u064f\u062d\u0630\u0641 \u0627\u0631\u062a\u0628\u0627\u0637 \u0643\u0644 \u0637\u0628\u064a\u0628. \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0645\u0631\u0633\u0644\u0629 \u0633\u0627\u0628\u0642\u0627\u064b \u062a\u0628\u0642\u0649 \u0641\u064a IQ Labs."},
gGX(){return"\u0625\u0636\u0627\u0641\u0629 \u062a\u0635\u0646\u064a\u0641"},
