ga_d(){return"\u0627\u0644\u062a\u0635\u0646\u064a\u0641"},
ga_p(){return"\u0628\u062f\u0648\u0646 \u062a\u0635\u0646\u064a\u0641"},
gHc(){return"\u0628\u062f\u0648\u0646 \u062a\u0635\u0646\u064a\u0641"},
a_I(a){return"\u0647\u0644 \u062a\u0631\u064a\u062f \u062d\u0630\u0641 \u0627\u0644\u062a\u0635\u0646\u064a\u0641 \xab"+a+"\xbb\u061f"},
