gZe(){return"\u0625\u0631\u0633\u0627\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649"},
gYR(){return"\u0625\u0631\u0633\u0627\u0644 \u0625\u0644\u0649"},
Zj(a){return"\u0623\u064f\u0631\u0633\u0644\u062a \u0625\u0644\u0649 "+a},
Zg(a){return"\u062a\u0639\u0630\u0651\u0631 \u0627\u0644\u0625\u0631\u0633\u0627\u0644: "+a},
gahf(){return"\u062c\u0647\u0627\u062a \u0627\u0644\u0627\u062a\u0635\u0627\u0644 (\u0627\u0644\u0645\u0637\u0628\u0639\u0629\u060c \u0645\u062e\u062a\u0628\u0631 \u0627\u0644\u062e\u0631\u0627\u0637\u0629\u2026)"},
