gadw(){return"\u0628\u06c6 \u062f\u06d5\u0633\u062a\u067e\u06ce\u06af\u06d5\u0647\u0634\u062a\u0646\u0627 \u062a\u06d5\u0645\u0627\u0645 \u06a4\u0627\u0644\u0627 \u0628\u0647\u06ce\u0644\u06d5. \u067e\u06c6\u0644\u06d5\u06a9\u06ce \u06cc\u0627\u0646 \u0632\u06ce\u062f\u06d5\u062a\u0631 \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5 \u0648 \u0626\u06d5\u06a4 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u062f\u06ce \u062a\u0646\u06ce \u06a9\u06d5\u06cc\u0633\u06ce\u0646 \u0648\u0627\u0646 \u067e\u06c6\u0644\u0627\u0646 \u0628\u06cc\u0646\u06cc\u062a \u0648 \u06a9\u0627\u0631\u06ce \u0644 \u0633\u06d5\u0631 \u06a9\u06d5\u062a\u060c \u062f \u0647\u06d5\u0645\u06cc \u0628\u06d5\u0634\u06ce\u0646 \u0626\u06d5\u067e\u06cc \u062f\u0627. \u0628\u06d5\u0695\u06ce\u06a4\u06d5\u0628\u06d5\u0631 \u0686 \u062c\u0627\u0631\u0627\u0646 \u0633\u0646\u0648\u0648\u0631\u062f\u0627\u0631 \u0646\u0627\u0628\u06cc\u062a. \u062f\u06d5\u0633\u062a\u067e\u06ce\u06af\u06d5\u0647\u0634\u062a\u0646\u0627 \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u0627\u0646 \u06cc\u0627\u0646 \u0695\u0627\u067e\u06c6\u0631\u062a\u0627\u0646 \u0646\u06d5\u062f\u06d5 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06ce \u0633\u0646\u0648\u0648\u0631\u062f\u0627\u0631: \u06a9\u06c6\u06a9\u0631\u0627\u0648\u06ce\u0646 \u0648\u06cc \u062a\u0646\u06ce \u0626\u06d5\u0648 \u067e\u06c6\u0644 \u062f\u06af\u0631\u0646."},
PN(a,b){return"\u062c\u0647\u06ce \u0628\u06a9\u0627\u0631\u0647\u0627\u062a\u06cc: "+a+" \u0698 "+b+" GB \u06cc\u06ce\u0646 \u0628\u06ce \u0628\u06d5\u0631\u0627\u0645\u0628\u06d5\u0631"},
PM(a,b,c){return""+a+" GB \u062f\u06af\u06d5\u0644 \u0628\u06d5\u0634\u062f\u0627\u0631\u0628\u0648\u0648\u0646\u06ce \u062f\u0627\u0646\u06d5. \u067e\u0634\u062a\u06cc \u0648\u06ce\u060c "+b+" \u0628\u06c6 \u0647\u06d5\u0631 100 GB \u062f \u0633\u0627\u0644\u06ce \u062f\u0627\u060c \u0644 \u062f\u0648\u06cc\u06a4 \u062a\u06ce\u06a9\u0695\u0627\u06cc\u0627 \u0628\u06a9\u0627\u0631\u0626\u06cc\u0646\u0627\u0646\u0627 \u062a\u06d5 \u062f \u0661\u0662 \u0647\u06d5\u06cc\u06a4\u06ce\u0646 \u0628\u0648\u0631\u06cc \u062f\u0627 (\u0646\u0648\u06a9\u06d5 "+c+")."},
PL(a){return"\u062a\u06ce\u0686\u0648\u0648\u06cc\u0627 \u0647\u06cc\u06a4\u06cc\u06a9\u0631\u06cc \u06cc\u0627 \u062c\u0647\u06ce \u067e\u0627\u0631\u0627\u0633\u062a\u0646\u06ce \u0628\u06c6 \u06a4\u06ce \u0633\u0627\u0644\u06ce: "+a},
